baseCss:
.aha-marketing-cards{
  container:aha-marketing-cards / inline-size;
  background:transparent;
  color:var(--aha-text-default);
  font-family:var(--aha-font-product);
}
.aha-marketing-cards *{box-sizing:border-box}
:where(.aha-marketing-card) h3,:where(.aha-marketing-card) p,:where(.aha-marketing-card) blockquote,:where(.aha-marketing-card) figure,figure:where(.aha-marketing-card){margin:0}
:where(.aha-marketing-card) blockquote{padding:0}
:where(.aha-marketing-cards) ol{margin:0;padding:0}
.aha-marketing-cards__grid{
  display:grid;grid-template-columns:repeat(3,minmax(0,1fr));
  gap:var(--aha-space-32);
  max-width:72rem;margin:0 auto;
  padding:var(--aha-space-64) var(--aha-space-24);
  list-style:none;
}
.aha-marketing-card{
  position:relative;
  display:flex;flex-direction:column;
  height:100%;
  background:var(--aha-bg-container);
  color:var(--aha-text-default);
  font-family:var(--aha-font-product);
  border:1px solid var(--aha-border-default);
  border-radius:var(--aha-radius-marketing);
  overflow:hidden;
}
.aha-marketing-card *{box-sizing:border-box}
.aha-marketing-card__media{
  display:flex;align-items:center;justify-content:center;
  width:100%;
  background:var(--aha-bg-container-secondary);
  color:var(--aha-icon-muted);
  overflow:hidden;
}
.aha-marketing-card__media--16x9{aspect-ratio:16 / 9}
.aha-marketing-card__media--3x2{aspect-ratio:3 / 2}
.aha-marketing-card__media img{display:block;width:100%;height:100%;object-fit:cover}
.aha-marketing-card__media--fill{aspect-ratio:auto;background:none}
.aha-marketing-card__media--fill img{height:auto;object-fit:fill}
.aha-marketing-card__media--pink-frame{position:relative;background:var(--aha-vivid-pink-100)}
.aha-marketing-card__splash{position:absolute;inset:0;overflow:hidden;container-type:size;pointer-events:none;--splash-across:.5;--splash-width:calc(4.5*min(100cqw,100cqh))}
@supports (width:calc(1px*sqrt(4)*tan(atan2(1px,1px)))){
  .aha-marketing-card__splash{--splash-width:calc(4.5*min(100cqw,100cqh)*sqrt(max(1,tan(atan2(100cqw,100cqh))*9/16,9/16/tan(atan2(100cqw,100cqh)))))}
}
.aha-marketing-card__splash>img{position:absolute;display:block;max-width:none;height:auto;width:var(--splash-width);left:calc(var(--splash-across)*100cqw - var(--splash-width)*0.516209);top:calc(55cqh - var(--splash-width)*0.418953)}
.aha-marketing-card__media .aha-marketing-card__splash>img{height:auto;object-fit:fill}
.aha-marketing-card__media--pink-frame>.aha-marketing-card__shot{position:relative;width:auto;height:auto;max-width:calc(100% - 2*var(--aha-space-16));max-height:calc(100% - 2*var(--aha-space-16));object-fit:contain;border-radius:var(--aha-radius-default)}
.aha-marketing-card__body{
  display:flex;flex-direction:column;flex:1;
  gap:var(--aha-space-12);
  padding:var(--aha-space-24);
}
.aha-marketing-card__eyebrow{
  font-size:var(--aha-size-sm);
  font-weight:var(--aha-weight-semibold);
  letter-spacing:var(--aha-letter-spacing-subheadings);
  text-transform:uppercase;
  color:var(--aha-color-primary);
}
.aha-marketing-card__title{
  font-size:var(--aha-size-xl);
  font-weight:var(--aha-weight-semibold);
  line-height:var(--aha-line-height-heading);
  color:var(--aha-text-default);
}
.aha-marketing-card__text{
  font-size:var(--aha-size-l);
  line-height:var(--aha-line-height-body);
  color:var(--aha-text-secondary);
}
.aha-marketing-card__meta{
  font-size:var(--aha-size-default);
  line-height:var(--aha-line-height-body);
  color:var(--aha-text-tertiary);
}
.aha-marketing-card__more{
  display:inline-flex;align-items:center;gap:var(--aha-space-8);
  margin-top:auto;
  font-size:var(--aha-size-default);
  font-weight:var(--aha-weight-semibold);
  color:var(--aha-text-default);
}
.aha-marketing-card__link{color:inherit;text-decoration:none}
.aha-marketing-card__link::after{content:"";position:absolute;inset:0}
.aha-marketing-card__link:focus-visible{outline:none}
.aha-marketing-card:has(.aha-marketing-card__link:focus-visible){
  outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2);
}
.aha-marketing-card--linked{
  transition:transform var(--aha-motion-mid) var(--aha-ease-out),box-shadow var(--aha-motion-mid) var(--aha-ease-out),border-color var(--aha-motion-mid) var(--aha-ease-out);
}
.aha-marketing-card--linked:hover{
  transform:translateY(calc(-1 * var(--aha-space-4)));
  border-color:var(--aha-border-hover);
  box-shadow:0 var(--aha-space-12) var(--aha-space-24) var(--aha-ink-a10);
}
.aha-marketing-card--linked:hover .aha-marketing-card__more{color:var(--aha-text-link-hover)}
@media (prefers-reduced-motion:reduce){
  .aha-marketing-card--linked{transition:none}
  .aha-marketing-card--linked:hover{transform:none}
}
@container aha-marketing-cards (max-width:991px){
  .aha-marketing-cards__grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--aha-space-24)}
}
@container aha-marketing-cards (max-width:767px){
  .aha-marketing-cards__grid{grid-template-columns:minmax(0,1fr);padding:var(--aha-space-48) var(--aha-space-24)}
}
@container aha-marketing-cards (max-width:479px){
  .aha-marketing-cards__grid{padding:var(--aha-space-32) var(--aha-space-16)}
  .aha-marketing-card__body{padding:var(--aha-space-20)}
}
.aha-marketing-cards__grid--image-led{grid-template-columns:repeat(2,minmax(0,1fr))}
.aha-marketing-cards__grid--image-led>li:first-child:nth-last-child(odd){grid-column:1 / -1}
.aha-marketing-cards__grid--image-led>li:first-child:nth-last-child(odd) .aha-marketing-card{display:grid;grid-template-columns:2fr 1fr;align-items:center}
.aha-marketing-cards__grid--image-led .aha-marketing-card__media:not(.aha-marketing-card__media--pink-frame){aspect-ratio:auto}
.aha-marketing-cards__grid--image-led .aha-marketing-card__media:not(.aha-marketing-card__media--pink-frame) img{height:auto;object-fit:contain}
.aha-marketing-cards__grid--image-led .aha-marketing-card__title{font-size:var(--aha-size-h4)}
@media (max-width:767px){
  .aha-marketing-cards__grid--image-led{grid-template-columns:minmax(0,1fr);gap:var(--aha-space-24)}
  .aha-marketing-cards__grid--image-led>li:first-child:nth-last-child(odd) .aha-marketing-card{display:flex;align-items:stretch}
}
.aha-marketing-cards__grid--row{grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--aha-space-24)}
@container aha-marketing-cards (max-width:767px){
  .aha-marketing-cards__grid--row{grid-template-columns:minmax(0,1fr)}
}
@container aha-marketing-cards (min-width:992px){
  .aha-marketing-cards__grid:not(.aha-marketing-cards__grid--image-led):not(.aha-marketing-cards__grid--row):has(>:first-child:last-child){grid-template-columns:minmax(0,36rem);justify-content:center}
  .aha-marketing-cards__grid:not(.aha-marketing-cards__grid--image-led):not(.aha-marketing-cards__grid--row):has(>:nth-child(2):last-child),.aha-marketing-cards__grid:not(.aha-marketing-cards__grid--image-led):not(.aha-marketing-cards__grid--row):has(>:nth-child(4):last-child){grid-template-columns:repeat(2,minmax(0,1fr))}
  .aha-marketing-cards__grid:not(.aha-marketing-cards__grid--image-led):not(.aha-marketing-cards__grid--row):has(>:nth-child(3n+1):last-child:nth-child(n+7))>:last-child{grid-column:2}
  .aha-marketing-cards__grid:not(.aha-marketing-cards__grid--image-led):not(.aha-marketing-cards__grid--row):has(>:nth-child(3n+2):last-child:nth-child(n+5)){grid-template-columns:repeat(6,minmax(0,1fr))}
  .aha-marketing-cards__grid:not(.aha-marketing-cards__grid--image-led):not(.aha-marketing-cards__grid--row):has(>:nth-child(3n+2):last-child:nth-child(n+5))>*{grid-column:span 2}
  .aha-marketing-cards__grid:not(.aha-marketing-cards__grid--image-led):not(.aha-marketing-cards__grid--row):has(>:nth-child(3n+2):last-child:nth-child(n+5))>:nth-last-child(2){grid-column:2 / span 2}
  .aha-marketing-cards__grid:not(.aha-marketing-cards__grid--image-led):not(.aha-marketing-cards__grid--row):has(>:nth-child(3n+2):last-child:nth-child(n+5))>:last-child{grid-column:4 / span 2}
}
@container aha-marketing-cards (min-width:768px) and (max-width:991px){
  .aha-marketing-cards__grid:not(.aha-marketing-cards__grid--image-led):not(.aha-marketing-cards__grid--row):has(>:nth-child(odd):last-child)>:last-child{grid-column:1 / -1;justify-self:center;width:calc(50% - var(--aha-space-12))}
}

snippets.css:
.aha-marketing-card--pricing{overflow:visible}
.aha-marketing-card--pricing .aha-marketing-card__body{gap:var(--aha-space-24);padding:var(--aha-space-32)}
.aha-marketing-card__head{display:flex;flex-direction:column;gap:var(--aha-space-12)}
.aha-marketing-card__head-row{display:flex;align-items:flex-start;justify-content:space-between;gap:var(--aha-space-24)}
.aha-marketing-card__plan-row{display:flex;flex-wrap:wrap;align-items:center;gap:var(--aha-space-8)}
.aha-marketing-card__plan{font-size:var(--aha-size-xl);font-weight:var(--aha-weight-semibold);line-height:var(--aha-line-height-heading);color:var(--aha-text-default)}
.aha-marketing-card__plan-icon{display:flex;flex:none;align-items:center;justify-content:center;width:var(--aha-space-48);height:var(--aha-space-48);border-radius:var(--aha-radius-default);background:var(--aha-bg-accent);color:var(--aha-color-primary)}
